mapper.select:
SELECT *
FROM contract_project
WHERE bool_delete_enum = 0

    AND status = #{status}


    AND DATE_FORMAT(create_time,'%Y') = #{year}


    AND project_type & #{projectType}

order by id desc

        SELECT p.*
        FROM contract_project AS p
        
            INNER JOIN sys_project_user_link link on link.project_id = p.id and link.user_id = #{userId}
            and link.bool_delete_enum = 0
        

        
        
        
        
        
        
        

        

        WHERE p.bool_delete_enum = 0
        
            AND p.id = #{projectId}
        
        
            AND DATE_FORMAT(p.create_time,'%Y') = #{contractProjectFilesParam.year}
        
        
        
        
        
            AND p.project_attribute = #{contractProjectFilesParam.projectAttribute}
        
        
            AND p.project_type & #{contractProjectFilesParam.projectType}
        
        
            AND p.business_type = #{contractProjectFilesParam.businessType}
        
        
        
        
        
            AND p.structure_status = #{contractProjectFilesParam.structureStatus}
        
        
            AND p.contract_sign_body_id = #{contractProjectFilesParam.contractSignBodyId}
        
        
            AND p.is_building = #{contractProjectFilesParam.isBuilding}
        
        
            AND p.serial_number like concat('%',#{contractProjectFilesParam.name},'%') or p.name like
            concat('%',#{contractProjectFilesParam.name},'%') or p.short_name like
            concat('%',#{contractProjectFilesParam.name},'%')
        
        
            AND p.is_archive = #{contractProjectFilesParam.isArchive}
        
        order by id desc

SELECT
cp.*,
st.name AS structure_type_name,
ct.quantity_work as structure_quantity_work,
manageuser.name as projectManagerName,
createuser.name as createUserName,
lastupdateuser.name as lastUpdateUserName
FROM contract_project AS cp
left join contract_tech ct on ct.bool_delete_enum = false and cp.id = ct.project_id and ct.category_type = 2

    INNER JOIN sys_project_user_link pul ON pul.project_id = cp.id AND pul.bool_delete_enum = 0
    AND (pul.user_id = #{userId})

left join sys_user as manageuser on cp.project_manager_id = manageuser.id and manageuser.bool_delete_enum = 0
left join sys_user as createuser on cp.user_id = createuser.id and createuser.bool_delete_enum = 0
left join sys_user as lastupdateuser on cp.last_update_user_id = lastupdateuser.id and
lastupdateuser.bool_delete_enum = 0
LEFT JOIN sys_structure_type AS st on cp.structure_type_id = st.id
WHERE cp.bool_delete_enum = 0

    AND find_in_set(#{projectContentId},cp.project_content)


    and cp.structure_status = #{structureStatus}


    and cp.structure_type_id = #{structureTypeId}


    and cp.status = #{status}


    and cp.settlement_status = #{settlementStatus}








    and (cp.short_name like concat('%', #{noOrProjectName}, '%')
    or cp.serial_number like concat('%',#{noOrProjectName},'%')
    or cp.short_name like concat('%',#{noOrProjectName},'%')
    )


    AND (cp.project_manager_id in (select id from sys_user where bool_delete_enum = 0 and name like
    concat('%',#{signerName},'%'))
    or
    cp.sales_leader_id in (select id from sys_user where bool_delete_enum = 0 and name like
    concat('%',#{signerName},'%')))


    and cp.address like concat('%',#{address},'%')


    and cp.customer_unit like concat('%',#{customerUnit},'%')


    AND cp.business_type = #{businessType}


    AND cp.project_type & #{projectType}


    and cp.out_finish_status = #{outFinishStatus}


    and cp.out_finish_status = #{outFinishStatus} and cp.status = 1


    and DATE_FORMAT(cp.create_time,'%Y') = #{year}


    and contract_sign_body_id = #{contractSignBodyId}


    and DATE_FORMAT(cp.create_time,'%Y') = DATE_FORMAT(#{yearDate},'%Y')


    AND EXISTS(
    select 1 from project_branch_company_link pbcl
    where pbcl.bool_delete_enum = FALSE
    and pbcl.branch_company_id = #{branchCompanyId}
    and pbcl.project_id = cp.id
    )


    and cp.project_attribute = #{projectAttribute}


    and cp.is_building = #{isBuilding}


    and cp.is_effective = #{isEffective}

order by cp.create_time desc

SELECT
cp.*
FROM contract_project cp

    INNER JOIN sys_project_user_link pul ON pul.project_id = cp.id AND pul.bool_delete_enum = 0
    and pul.user_id = #{userId}

WHERE cp.bool_delete_enum = 0

    and cp.project_type & #{projectType}


    and cp.status = #{status}


    and cp.settlement_status = #{settlementStatus}


    and cp.lump_sum_system_type & #{lumpSumSystemType}


    and cp.level & #{level} > 0

order by cp.id desc

select distinct cp.contract_type, cp.id, cp.serial_number, cp.name, cp.short_name, cp.business_type, cp.project_type, cp.contract_sign_body_id, bc.name as contract_sign_body_name, cp.settlement_status, cp.is_tax, cp.invoice_type, cp.pay_type, cp.tax_rate, cp.project_manager_id, cp.sales_leader_id, (SELECT `name` FROM sys_user WHERE bool_delete_enum = 0 AND id = cp.project_manager_id) AS project_manager_name, cp.status, cp.signer_id, cp.signer_name, cp.signing_date, cp.management_fee_rate, cp.contract_amount, cp.settlement_amount, cp.collection_amount, cp.invoice_amount, cp.happened_amount, cp.customer_unit,
(select count(*) from contract_collection where bool_delete_enum = 0 and project_id = cp.id and audit_status = 1) as un_check_collection_count, (select count(*) from contract_invoice where bool_delete_enum = 0 and project_id = cp.id and audit_status = 1) as un_check_invoice_count
from contract_project as cp left join sys_branch_company bc on cp.contract_sign_body_id = bc.id and bc.bool_delete_enum = 0
INNER JOIN sys_user u on cp.project_manager_id = u.id and u.bool_delete_enum = 0 AND u.`name` like concat('%',#{projectManagerName},'%')
INNER JOIN sys_project_user_link as pul on pul.project_id = cp.id and pul.user_id = #{userId}
where cp.bool_delete_enum = 0
and cp.id = #{projectId}
and cp.settlement_status = #{settlementStatus}
and cp.status = #{status}
and DATE_FORMAT(cp.create_time,'%Y') = #{year}
and cp.serial_number like concat('%',#{serialNumber},'%')
and cp.name like concat('%',#{name},'%')
and cp.customer_unit like concat('%',#{customerUnit},'%')
order by cp.settlement_status asc, cp.id desc

select * from contract_project
where bool_delete_enum = 0

    and id = #{projectId}


    and (name like CONCAT('%',#{name},'%')
    or short_name like CONCAT('%',#{name},'%'))


    and date_format(create_time, '%Y') = #{year}


    and (id in (select project_id from sys_project_user_link
    where bool_delete_enum = 0 and user_id =#{userId})
    or user_id = #{userId})


    and project_type & #{projectType}


    and lump_sum_system_type & #{lumpSumSystemType}

SELECT
cp.*
FROM
contract_project AS cp
INNER JOIN sys_project_user_link AS pul ON cp.id = pul.project_id and pul.bool_delete_enum = 0
WHERE cp.bool_delete_enum = 0


    AND pul.user_id = #{userId}








    AND DATE_FORMAT( cp.start_date, '%Y' ) = #{year}


    AND cp.status = #{status}


    AND (cp.short_name like concat('%',#{noName},'%')
    or cp.serial_number like concat('%',#{noName},'%')
    or cp.name like concat('%',#{noName},'%'))


    AND cp.project_type & #{projectType}


    AND cp.settlement_status = #{settlementStatus}


    AND cp.lump_sum_system_type & #{lumpSumSystemType}

-- GROUP BY cp.id

    AND cp.level & #{level}

GROUP BY cp.id
ORDER BY cp.id desc

select ifnull(sum(contract_amount), 0)
from contract_project
where bool_delete_enum = 0

    and project_type & #{projectType}


    and DATE_FORMAT(create_time, '%Y')= #{year}


    and status = #{status}

select contract_amount,settlement_amount,signing_date,signer_name, id 'project.id', name 'project.name', short_name 'project.short_name', serial_number 'project.serial_number' from contract_project where bool_delete_enum = 0
and id in
#{projectId}
and 1 = 0
and customer_unit = #{name}
and (customer_unit is null or customer_unit = '')
and business_type = #{businessType}
and date(create_time) >= date(#{startDate})
and date(create_time) <= date(#{endDate})

select * from contract_project

    
        status=#{status}
    
    
        settlement_status=#{settlementStatus}

SELECT cp.id 'project.id', cp.name 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', cp.status, cp.order_source_type, cp.settlement_status, cp.project_content, cp.contract_amount, cp.settlement_amount, cp.happened_amount, cp.collection_amount, cp.invoice_amount FROM contract_project cp
INNER JOIN sys_project_user_link pul ON pul.project_id = cp.id AND pul.bool_delete_enum = 0 AND pul.user_id = #{userId}
cp.bool_delete_enum = 0
AND DATE_FORMAT( cp.create_time, '%Y' ) = #{year}
and cp.product_category & #{productType} > 0
and cp.order_source_type = #{orderSourceType}
and cp.name like concat('%',#{name},'%')
and cp.status = #{projectStatus}
and cp.status = 4 and cp.settlement_status = 0
and cp.settlement_status = 1
order by cp.id desc

select cp.id, cp.id 'project.id', cp.name, cp.name 'project.name', cp.short_name, cp.short_name 'project.short_name', cp.serial_number, cp.serial_number 'project.serial_number', cp.business_type, cp.project_type, cp.order_source_type, cp.contract_amount, cp.status, cp.settlement_status , cp.settlement_amount, cp.collection_amount, cp.happened_amount, 0 cost_amount, (case cp.settlement_status when 0 then cp.contract_amount-cp.collection_amount when 1 then cp.settlement_amount-cp.collection_amount end
) receivable_amount, (cp.collection_amount - cp.happened_amount) available_balance, cv.attachment_ids as settlement_attachment_ids from contract_project cp left join contract_visa cv on cp.id = cv.project_id and cv.type = 2 and cv.status = 2 and cv.bool_delete_enum = 0 where cp.bool_delete_enum = 0
and DATE_FORMAT(cp.create_time, '%Y') = #{year}
and cp.id= #{projectId}
and cp.business_type = #{businessType}
and cp.project_type & #{projectType}
and cp.order_source_type = #{orderSourceType}
and cp.settlement_status =#{settlementStatus}
and cp.status = #{status}
order by cp.id desc

SELECT * FROM contract_project where bool_delete_enum=0 AND status=1 AND DATE_FORMAT(create_time,'%Y')=DATE_FORMAT(#{localDateTime},'%Y')
AND (serial_number like concat('%',#{serialNumber},'%') or short_name like concat('%',#{serialNumber},'%') or name like concat('%',#{serialNumber},'%') )
AND id IN (SELECT par.project_id FROM mes_building_nest_cut_machine_part_separate sep LEFT JOIN tech_machine_part par ON sep.product_id = par.id WHERE sep.bool_delete_enum = 0
AND sep.nest_cut_id IN
#{item}
AND sep.nest_cut_id is null
AND par.project_id IN
#{item}
)

SELECT a.* FROM contract_project a WHERE id IN ( SELECT DISTINCT a.project_id FROM mes_building_task_process a INNER JOIN mes_building_process p ON p.id = a.process_id WHERE a.bool_delete_enum=0 AND a.task_type_enum = 1 AND p.type = #{type}
AND a.task_order_id IN
#{taskOrderId}
AND a.task_order_id is null
) AND a.bool_delete_enum = 0

select id, name, short_name, serial_number from contract_project where bool_delete_enum = 0
and id in
#{id}

select cp.id, cp.short_name, cp.serial_number, cp.project_attribute, cp.business_type, cp.structure_status, cp.lump_sum_system_type, cp.signing_date, cp.signing_date AS planCreateDate, suser.name AS projectManagerName from contract_project cp LEFT JOIN sys_user suser on suser.id = cp.project_manager_id
INNER JOIN sys_project_user_link link on link.project_id = cp.id and link.user_id = #{userId} and link.bool_delete_enum = 0
where cp.bool_delete_enum = 0
and date_format(cp.create_time,'%Y') = #{year}
and cp.lump_sum_system_type & #{lumpSumSystemType}
and cp.project_type & #{projectType}
and (cp.name like concat('%',#{name},'%') or cp.short_name like concat('%',#{name},'%') or cp.serial_number like concat('%',#{name},'%'))

SELECT DISTINCT cp.* , CASE WHEN plan.id IS NULL THEN 0 ELSE 1 END AS have_plan
FROM contract_project cp
LEFT JOIN plan_monomer plan ON plan.project_id = cp.id AND plan.bool_delete_enum = 0

    INNER JOIN sys_project_user_link link on link.project_id = cp.id and link.user_id = #{userId}
    and link.bool_delete_enum = 0


    AND cp.bool_delete_enum = 0
    
        AND cp.status = #{status}
    
    
        AND cp.name LIKE CONCAT('%', #{noOrName}, '%')
        OR cp.serial_number LIKE CONCAT('%', #{noOrName}, '%')
    
    
        AND cp.start_date BETWEEN #{firstDayOfYear} AND #{lastDayOfYear}
    
    
        AND cp.project_type & #{projectType}
    
    
        AND cp.lump_sum_system_type & #{lumpSumSystemType}
    

ORDER BY have_plan ASC , cp.create_time DESC

SELECT * FROM contract_project cp
INNER JOIN sys_project_user_link link ON link.project_id = cp.id AND link.bool_delete_enum = 0 AND link.user_id = #{userId}
WHERE cp.id IN
#{id}
ORDER BY cp.create_time DESC

SELECT
pro.*,
sus.name as user_id ,
su.name as project_manager_id
FROM
`contract_project` pro
LEFT JOIN sys_user sus on sus.id = pro.user_id
and sus.bool_delete_enum = 0
LEFT JOIN sys_user su on su.id = pro.project_manager_id
where pro.bool_delete_enum = 0

    and project_attribute = #{projectAttribute}


    and project_manager_id = #{projectManagerId}


    and project_id = #{projectId}


    and start_date = #{startDate}


    and end_date = #{endDate}

select id, serial_number, name, short_name,project_attribute,project_manager_id from contract_project where id in
#{projectId}
and bool_delete_enum = 0

SELECT a.id, a.serial_number, a.short_name, a.name, a.status, a.create_time FROM contract_project a WHERE bool_delete_enum = 0
AND DATE_FORMAT(a.create_time,'%Y') = #{year}
AND a.status = #{status}
AND a.id IN
#{projectId}
ORDER BY a.create_time DESC

SELECT cp.id, cp.create_time, cp.level, cp.id AS 'project.id', cp.serial_number AS 'project.serialNumber', cp.NAME AS 'project.name', cp.short_name AS 'project.shortName', cp.business_type, cp.project_type, cp.contract_sign_body_id, bc.NAME AS contract_sign_body_name, cp.settlement_status, cp.project_attribute, cp.is_tax, cp.invoice_type, cp.pay_type, cp.tax_rate, cp.project_manager_id, ( SELECT `name` FROM sys_user WHERE bool_delete_enum = 0 AND id = cp.project_manager_id ) AS project_manager_name, cp.STATUS, cp.signer_id, cp.signer_name, cp.sales_leader_id, null AS sales_leader_name, cp.signing_date, cp.settlement_amount, cp.collection_amount, cp.invoice_amount, cp.happened_amount, cp.customer_unit, cp.address, cp.structure_status, ( SELECT count(*) FROM contract_collection WHERE bool_delete_enum = 0 AND project_id = cp.id AND audit_status = 1 ) AS un_check_collection_count, ( SELECT count(*) FROM contract_invoice WHERE bool_delete_enum = 0 AND project_id = cp.id AND audit_status = 1 ) AS un_check_invoice_count, cp.country_id, cp.country_name, cp.province_id, cp.province_name, cp.city_id, cp.city_name, cp.start_date, cp.end_date, cp.contract_amount AS amount, cp.currency_type, cp.margin_amount AS cashDeposit, cp.margin_type, cp.pay_type_desc FROM contract_project AS cp LEFT JOIN sys_branch_company bc ON cp.contract_sign_body_id = bc.id AND bc.bool_delete_enum = 0 WHERE cp.bool_delete_enum = 0
AND YEAR(cp.create_time) = YEAR(#{year})
AND cp.settlement_status = #{settlementStatus}
AND cp.level & #{level} > 0
AND cp.project_attribute = #{projectAttribute}
AND cp.project_manager_id = #{projectManagerId}
AND (cp.sales_leader_id = #{salesLeaderId} OR (cp.sales_leader_id IS NULL and cp.signer_id = #{salesLeaderId}))
AND cp.id = #{projectId}
GROUP BY cp.id ORDER BY cp.settlement_status ASC, cp.id DESC

SELECT project.id project_id, project.`name` project_name, project.short_name short_name, project.serial_number serial_number, monomer.id monomer_id, monomer.`name` monomer_name, area.id area_id, area.`name` area_name from contract_project project left join plan_monomer monomer on project.id = monomer.project_id and monomer.bool_delete_enum = 0 left join plan_area area on monomer.id = area.monomer_id and area.bool_delete_enum = 0 left join mes_building_task_order orde on project.id = orde.project_id and orde.bool_delete_enum = 0 left join mes_building_production_line line on orde.production_line_id = line.id and line.bool_delete_enum = 0 where project.bool_delete_enum = 0
and project.id in
#{projectId}
and line.workshop_id = #{workShopId}
AND DATE_FORMAT(orde.create_time, '%Y') = DATE_FORMAT(#{dateTime}, '%Y')

SELECT a.id, a.serial_number, a.short_name, a.name, a.status, a.create_time FROM contract_project a WHERE bool_delete_enum = 0
AND DATE_FORMAT(a.create_time,'%Y') = #{year}
AND a.status = #{status}
AND a.id IN
#{projectId}
ORDER BY a.create_time DESC
